// Package service keeps a program running on Linux (systemd), macOS (launchd)
// and Windows (a scheduled task). The files it writes are generated by pure
// functions; the real commands go through an injectable Runner, so tests fake
// them and install nothing.
package service

import (
	"context"
	"encoding/base64"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"runtime"
	"strings"

	"github.com/CharlesMod/wasp/profile"
)

// Spec is one program to keep running.
type Spec struct {
	Name             string // letters, digits, dot, dash, underscore
	Description      string
	Exec             []string // program and arguments
	Env              map[string]string
	WorkDir          string
	User             bool // per-user service even when running as root
	RestartOnFailure bool
	LogFile          string
}

// State is what the platform says about a service.
type State struct {
	Installed bool
	Running   bool
	Failed    bool
	Detail    string // the platform's word: "active", "stopped", "Ready"...
	LastExit  string // the last exit status when the platform keeps one
}

// Result says what Install did, including what it could not do.
type Result struct {
	Files []string // files written
	Notes []string // honest caveats (linger refused, and so on)
}

// Runner runs one real command. Tests hand a fake.
type Runner func(ctx context.Context, name string, args ...string) ([]byte, error)

// ExecRunner runs commands for real.
func ExecRunner(ctx context.Context, name string, args ...string) ([]byte, error) {
	return exec.CommandContext(ctx, name, args...).CombinedOutput()
}

// Manager installs services for one platform and home.
type Manager struct {
	GOOS     string
	Home     string // the user's home: unit and plist files go under it
	StateDir string // where Windows wrapper scripts live
	UID      int
	Root     bool // running as root: system units unless Spec.User
	Run      Runner
}

// Default is a Manager for this machine.
func Default() *Manager {
	home, _ := os.UserHomeDir()
	return &Manager{
		GOOS: runtime.GOOS, Home: home,
		StateDir: filepath.Join(profile.InstallRoot(), "services"),
		UID:      os.Getuid(), Root: os.Getuid() == 0 && runtime.GOOS != "windows",
		Run: ExecRunner,
	}
}

// Install, Start, Stop, Status and Uninstall act through Default().
func Install(ctx context.Context, s Spec) (Result, error) { return Default().Install(ctx, s) }
func Start(ctx context.Context, name string) error        { return Default().Start(ctx, name) }
func Stop(ctx context.Context, name string) error         { return Default().Stop(ctx, name) }
func Status(ctx context.Context, name string) (State, error) {
	return Default().Status(ctx, name)
}
func Uninstall(ctx context.Context, name string) error { return Default().Uninstall(ctx, name) }

var nameRe = regexp.MustCompile(`^[A-Za-z0-9][A-Za-z0-9._-]*$`)

// Validate says why a spec cannot be installed.
func (s Spec) Validate() error {
	if !nameRe.MatchString(s.Name) {
		return fmt.Errorf("service: bad name %q (letters, digits, . - _)", s.Name)
	}
	if len(s.Exec) == 0 || s.Exec[0] == "" {
		return errors.New("service: Exec is empty")
	}
	return nil
}

func (m *Manager) system(s Spec) bool { return m.Root && !s.User && m.GOOS != "windows" }

// Label is the launchd label.
func Label(name string) string { return "wasp." + name }

func (m *Manager) unitPath(name string, system bool) string {
	if system {
		return "/etc/systemd/system/" + name + ".service"
	}
	return filepath.Join(m.Home, ".config", "systemd", "user", name+".service")
}

func (m *Manager) plistPath(name string, system bool) string {
	if system {
		return "/Library/LaunchDaemons/" + Label(name) + ".plist"
	}
	return filepath.Join(m.Home, "Library", "LaunchAgents", Label(name)+".plist")
}

func (m *Manager) wrapperPath(name string) string {
	return filepath.Join(m.StateDir, name+".ps1")
}

func (m *Manager) domain(system bool) string {
	if system {
		return "system"
	}
	return fmt.Sprintf("gui/%d", m.UID)
}

func (m *Manager) sysctl(system bool, args ...string) (string, []string) {
	if system {
		return "systemctl", args
	}
	return "systemctl", append([]string{"--user"}, args...)
}

func writeFile(path, body string, mode os.FileMode) error {
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return err
	}
	return os.WriteFile(path, []byte(body), mode)
}

// Install writes the service's files and enables it.
func (m *Manager) Install(ctx context.Context, s Spec) (Result, error) {
	var res Result
	if err := s.Validate(); err != nil {
		return res, err
	}
	if s.LogFile != "" {
		_ = os.MkdirAll(filepath.Dir(s.LogFile), 0o755)
	}
	switch m.GOOS {
	case "linux":
		sys := m.system(s)
		p := m.unitPath(s.Name, sys)
		if err := writeFile(p, Unit(s, sys), 0o644); err != nil {
			return res, err
		}
		res.Files = append(res.Files, p)
		cmd, a := m.sysctl(sys, "daemon-reload")
		if out, err := m.Run(ctx, cmd, a...); err != nil {
			return res, cmdErr(cmd, a, out, err)
		}
		cmd, a = m.sysctl(sys, "enable", "--now", s.Name+".service")
		if out, err := m.Run(ctx, cmd, a...); err != nil {
			return res, cmdErr(cmd, a, out, err)
		}
		if !sys {
			if out, err := m.Run(ctx, "loginctl", "enable-linger"); err != nil {
				res.Notes = append(res.Notes, "could not enable linger ("+oneLine(out, err)+
					"): the service runs only while you are logged in")
			}
		}
	case "darwin":
		sys := m.system(s)
		p := m.plistPath(s.Name, sys)
		if err := writeFile(p, Plist(s), 0o644); err != nil {
			return res, err
		}
		res.Files = append(res.Files, p)
		_, _ = m.Run(ctx, "launchctl", "bootout", m.domain(sys)+"/"+Label(s.Name)) // a stale load is fine to lose
		if out, err := m.Run(ctx, "launchctl", "bootstrap", m.domain(sys), p); err != nil {
			return res, cmdErr("launchctl", []string{"bootstrap", m.domain(sys), p}, out, err)
		}
	case "windows":
		w := m.wrapperPath(s.Name)
		if err := writeFile(w, WindowsWrapper(s), 0o644); err != nil {
			return res, err
		}
		x := filepath.Join(m.StateDir, s.Name+".xml")
		if err := writeFile(x, string(UTF16LE(TaskXML(s, w))), 0o644); err != nil {
			return res, err
		}
		res.Files = append(res.Files, w, x)
		args := []string{"/create", "/tn", s.Name, "/xml", x, "/f"}
		if out, err := m.Run(ctx, "schtasks", args...); err != nil {
			return res, cmdErr("schtasks", args, out, err)
		}
		if out, err := m.Run(ctx, "schtasks", "/run", "/tn", s.Name); err != nil {
			res.Notes = append(res.Notes, "installed, but did not start now ("+oneLine(out, err)+"); it starts at logon")
		}
	default:
		return res, fmt.Errorf("service: unsupported OS %q", m.GOOS)
	}
	return res, nil
}

// Start starts an installed service.
func (m *Manager) Start(ctx context.Context, name string) error {
	switch m.GOOS {
	case "linux":
		cmd, a := m.linuxCmd("start", name+".service")
		return m.try(ctx, cmd, a...)
	case "darwin":
		sys := m.hasSystemPlist(name)
		if _, err := os.Stat(m.plistPath(name, sys)); err == nil {
			_, _ = m.Run(ctx, "launchctl", "bootstrap", m.domain(sys), m.plistPath(name, sys)) // already loaded is fine
		}
		return m.try(ctx, "launchctl", "kickstart", m.domain(sys)+"/"+Label(name))
	case "windows":
		return m.try(ctx, "schtasks", "/run", "/tn", name)
	}
	return fmt.Errorf("service: unsupported OS %q", m.GOOS)
}

// Stop stops a service. On macOS it unloads the job, which KeepAlive would
// otherwise restart; Start loads it again.
func (m *Manager) Stop(ctx context.Context, name string) error {
	switch m.GOOS {
	case "linux":
		cmd, a := m.linuxCmd("stop", name+".service")
		return m.try(ctx, cmd, a...)
	case "darwin":
		return m.try(ctx, "launchctl", "bootout", m.domain(m.hasSystemPlist(name))+"/"+Label(name))
	case "windows":
		m.endTree(ctx, name)
		return m.try(ctx, "schtasks", "/end", "/tn", name)
	}
	return fmt.Errorf("service: unsupported OS %q", m.GOOS)
}

// endTree ends the program a Windows task runs, and everything it started.
// schtasks /end stops only the task's own process; the wrapper's program and
// its children live on, holding their files. The wrapper is found by its
// command line, which names this service's wrapper script and nothing else's,
// so no process another program owns is touched.
func (m *Manager) endTree(ctx context.Context, name string) {
	w := strings.ReplaceAll(m.wrapperPath(name), "'", "''")
	script := "Get-CimInstance Win32_Process | Where-Object { $_.Name -eq 'powershell.exe' -and $_.CommandLine -and " +
		"$_.CommandLine.Contains('" + w + "') } | ForEach-Object { taskkill.exe /T /F /PID $_.ProcessId | Out-Null }"
	_, _ = m.Run(ctx, "powershell.exe", "-NoProfile", "-NonInteractive", "-EncodedCommand", EncodePS(script))
}

// EncodePS is a PowerShell script as -EncodedCommand takes it (base64 of
// UTF-16LE), so no quoting survives or breaks on its way through a command line.
func EncodePS(script string) string {
	return base64.StdEncoding.EncodeToString(UTF16LE(script)[2:])
}

// Uninstall stops, disables and removes the service's files.
func (m *Manager) Uninstall(ctx context.Context, name string) error {
	switch m.GOOS {
	case "linux":
		sys := m.Root && fileExists(m.unitPath(name, true))
		cmd, a := m.sysctl(sys, "disable", "--now", name+".service")
		_, _ = m.Run(ctx, cmd, a...)
		if err := os.Remove(m.unitPath(name, sys)); err != nil && !os.IsNotExist(err) {
			return err
		}
		cmd, a = m.sysctl(sys, "daemon-reload")
		_, _ = m.Run(ctx, cmd, a...)
	case "darwin":
		sys := m.hasSystemPlist(name)
		_, _ = m.Run(ctx, "launchctl", "bootout", m.domain(sys)+"/"+Label(name))
		if err := os.Remove(m.plistPath(name, sys)); err != nil && !os.IsNotExist(err) {
			return err
		}
	case "windows":
		m.endTree(ctx, name)
		if _, err := m.Run(ctx, "schtasks", "/query", "/tn", name); err == nil {
			_, _ = m.Run(ctx, "schtasks", "/end", "/tn", name)
			if err := m.try(ctx, "schtasks", "/delete", "/tn", name, "/f"); err != nil {
				return err
			}
		}
		_ = os.Remove(m.wrapperPath(name))
		_ = os.Remove(filepath.Join(m.StateDir, name+".xml"))
	default:
		return fmt.Errorf("service: unsupported OS %q", m.GOOS)
	}
	return nil
}

// Status asks the platform.
func (m *Manager) Status(ctx context.Context, name string) (State, error) {
	switch m.GOOS {
	case "linux":
		sys := m.Root && fileExists(m.unitPath(name, true))
		cmd, a := m.sysctl(sys, "show", name+".service", "-p", "LoadState", "-p", "ActiveState", "-p", "SubState", "-p", "ExecMainStatus", "-p", "Result")
		out, err := m.Run(ctx, cmd, a...)
		if err != nil {
			return State{}, cmdErr(cmd, a, out, err)
		}
		return ParseSystemctlShow(string(out)), nil
	case "darwin":
		sys := m.hasSystemPlist(name)
		out, err := m.Run(ctx, "launchctl", "print", m.domain(sys)+"/"+Label(name))
		if err != nil {
			// not loaded: installed only if its plist is on disk
			return State{Installed: fileExists(m.plistPath(name, sys)), Detail: "not loaded"}, nil
		}
		return ParseLaunchctlPrint(string(out)), nil
	case "windows":
		out, err := m.Run(ctx, "schtasks", "/query", "/tn", name, "/fo", "LIST", "/v")
		if err != nil {
			return State{Detail: "not installed"}, nil
		}
		return ParseSchtasksQuery(string(out)), nil
	}
	return State{}, fmt.Errorf("service: unsupported OS %q", m.GOOS)
}

func (m *Manager) hasSystemPlist(name string) bool {
	return m.Root && fileExists(m.plistPath(name, true))
}

func (m *Manager) linuxCmd(verb, unit string) (string, []string) {
	sys := m.Root && fileExists(m.unitPath(strings.TrimSuffix(unit, ".service"), true))
	return m.sysctl(sys, verb, unit)
}

// try runs a command and turns a failure into an error carrying its output.
func (m *Manager) try(ctx context.Context, name string, args ...string) error {
	out, err := m.Run(ctx, name, args...)
	if err != nil {
		return cmdErr(name, args, out, err)
	}
	return nil
}

func fileExists(p string) bool { _, err := os.Stat(p); return err == nil }

func oneLine(out []byte, err error) string {
	s := strings.TrimSpace(string(out))
	if i := strings.IndexByte(s, '\n'); i >= 0 {
		s = s[:i]
	}
	if s == "" && err != nil {
		s = err.Error()
	}
	return s
}

func cmdErr(name string, args []string, out []byte, err error) error {
	return fmt.Errorf("service: %s %s: %s", name, strings.Join(args, " "), oneLine(out, err))
}
